 @Test void ActualNextGenerationCommitsCompleteInputRequestLineageAndOwnerReceiptWithoutReplacingOldBody()throws Exception{setup(true);var f=h.h.h.h.f.data.nativeData().fixture().f();String beforeBody=f.jdbc.queryForObject("SELECT body_json FROM contents WHERE id=?",String.class,id);var before=f.jdbc.queryForMap("SELECT revision,body_revision,input_job_id,state FROM contents WHERE id=?",id);var result=prepare("fictional-supplement-new");assertEquals(2,result.accepted().generation());assertEquals("queued",result.accepted().state());assertEquals(1L,result.accepted().baseRevision());assertEquals(beforeBody,f.jdbc.queryForObject("SELECT body_json FROM contents WHERE id=?",String.class,id));assertEquals(before,f.jdbc.queryForMap("SELECT revision,body_revision,input_job_id,state FROM contents WHERE id=?",id));assertEquals(0,new JdbcJobRecords(f.source).byId(nextRoot()).callCount());assertEquals(1,new JdbcJobRecords(f.source).byId(h.identity.rootId()).callCount());assertEquals(h.identity.rootId(),new GenerationLineageService(new JdbcGenerationLineage(f.source),clock,JdbcReportPreparedInputs.ACTOR).read(nextRoot()).supersedesJobId());assertTrue(ReportPreparationInputProfile.complete(CanonicalJson.parse(result.prepared().input().snapshotJson())).command().explicitSupplement());assertEquals(1,builds);assertEquals(1,h.reportSends);assertEquals(result.prepared(),originals.find(result.prepared().scope()));}
